CALL { WITH a CALL { WITH a MATCH (a)-[r1:`USES_TOOL`]->(n1:`Tool`) WHERE n1 <> a RETURN n1, r1 } WITH n1, r1 LIMIT $countCap + 1 WITH collect({n1: n1, r1: r1}) AS found RETURN size(found) > $countCap AS cut1, found[..$countCap] AS f1 }
CALL { WITH f1 UNWIND f1 AS e WITH DISTINCT e.n1 AS n CALL { WITH n CALL { WITH n MATCH (n)-[:`FIXES`]->() RETURN 1 AS hit } WITH hit LIMIT $countCap + 1 RETURN count(*) AS degree } WITH collect({n: n, degree: degree, stopped: coalesce(n.`isBusy`, false) = true OR coalesce(n.`isBroken`, false) = true}) AS checked RETURN [c IN checked WHERE c.degree > $countCap | c.n] AS heavy2, [c IN checked WHERE c.degree <= $countCap AND NOT c.stopped | c.n] AS mids2, any(c IN checked WHERE c.stopped) AS stopped2 }
CALL { WITH a, f1, mids2 UNWIND f1 AS e WITH a, e, mids2 WHERE e.n1 IN mids2 WITH a, e, e.n1 AS n1 CALL { WITH a, n1 MATCH (n1)-[r2:`FIXES`]->(n2:`Tool`) WHERE n2 <> a AND n2 <> n1 RETURN n2, r2 } WITH e, n2, r2 LIMIT $countCap + 1 WITH collect(e{.*, n2: n2, r2: r2}) AS found RETURN size(found) > $countCap AS cut2, found[..$countCap] AS f2 }
CALL { WITH f2 UNWIND f2 AS e WITH DISTINCT e.n2 AS n CALL { WITH n CALL { WITH n MATCH (n)-[:`MADE_BY`]->() RETURN 1 AS hit } WITH hit LIMIT $countCap + 1 RETURN count(*) AS degree } WITH collect({n: n, degree: degree, stopped: coalesce(n.`isBusy`, false) = true OR coalesce(n.`isBroken`, false) = true}) AS checked RETURN [c IN checked WHERE c.degree > $countCap | c.n] AS heavy3, [c IN checked WHERE c.degree <= $countCap AND NOT c.stopped | c.n] AS mids3, any(c IN checked WHERE c.stopped) AS stopped3 }
CALL { WITH a, f2, mids3 UNWIND f2 AS e WITH a, e, mids3 WHERE e.n2 IN mids3 WITH a, e, e.n1 AS n1, e.n2 AS n2 CALL { WITH a, n1, n2 MATCH (n2)-[r3:`MADE_BY`]->(n3:`Maker`) WHERE n3 <> a AND n3 <> n1 AND n3 <> n2 RETURN n3, r3 } WITH DISTINCT n3 LIMIT $countCap + 1 RETURN count(n3) AS matches }
RETURN matches, cut1 OR cut2 AS bounded, stopped2 OR stopped3 AS stopListed, size(heavy2 + heavy3) AS supernodes

